import numpy as np
def update_edge_distance(edge_distance, local_opt_tour, edge_n_used):
    updated_edge_distance = np.copy(edge_distance)
    n = len(local_opt_tour)
    tour_edges = []
    for i in range(n):
        u = local_opt_tour[i]
        v = local_opt_tour[(i + 1) % n]
        tour_edges.append((u, v))
        tour_edges.append((v, u))
    max_utility = -1.0
    utilities = {}
    for u, v in tour_edges:
        util = edge_distance[u, v] / (1.0 + edge_n_used[u, v])
        utilities[(u, v)] = util
        if util > max_utility:
            max_utility = util
    penalty_factor = 0.1 * np.mean(edge_distance)
    for (u, v), util in utilities.items():
        if np.isclose(util, max_utility):
            edge_n_used[u, v] += 1
            updated_edge_distance[u, v] += penalty_factor
    avg_usage = np.mean(edge_n_used)
    for u in local_opt_tour:
        neighbors = np.argsort(edge_distance[u])
        for v in neighbors[1:6]:  
            if edge_n_used[u, v] <= avg_usage and (u, v) not in utilities:
                updated_edge_distance[u, v] *= 0.95
                updated_edge_distance[v, u] *= 0.95
    return updated_edge_distance
